package org.pacos.plugin.kafka.view;
import com.vaadin.flow.component.tabs.Tab; import com.vaadin.flow.component.tabs.Tabs; import com.vaadin.flow.component.orderedlayout.VerticalLayout; import org.pacos.base.window.DesktopWindow; import org.pacos.plugin.kafka.backend.connection.KafkaConnectionService; import org.pacos.plugin.kafka.backend.message.KafkaMessageService; import org.pacos.plugin.kafka.view.config.KafkaWindowConfig; import org.pacos.plugin.kafka.view.connection.KafkaConnectionView; import org.pacos.plugin.kafka.view.message.KafkaMessageView; import org.springframework.context.annotation.Scope; import org.springframework.stereotype.Component;
@Component @Scope("prototype") public class PanelKafka extends DesktopWindow {
 public PanelKafka(KafkaWindowConfig config,KafkaConnectionService connections,KafkaMessageService messages){super(config);Tabs tabs=new Tabs();Tab connectionsTab=new Tab("Connections");Tab messageTab=new Tab("Send message");tabs.add(connectionsTab,messageTab);VerticalLayout body=new VerticalLayout();KafkaConnectionView cv=new KafkaConnectionView(connections);KafkaMessageView mv=new KafkaMessageView(connections,messages);body.add(cv);tabs.addSelectedChangeListener(e->{body.removeAll();body.add(e.getSelectedTab()==connectionsTab?cv:mv);});add(tabs,body);}
}